UPDATE outbox_message
SET status = 'PROCESSING',
    claimed_at = #{claimedAt,jdbcType=TIMESTAMP}
WHERE id = #{id,jdbcType=VARCHAR}
  AND status = 'PENDING'


WITH cand AS MATERIALIZED (
    SELECT id FROM outbox_message
    WHERE status = 'PENDING' AND created_at < #{cutoff,jdbcType=TIMESTAMP}
    ORDER BY created_at ASC, id ASC
    LIMIT #{batchSize,jdbcType=INTEGER}
    FOR UPDATE SKIP LOCKED
)
UPDATE outbox_message o
SET status = 'PROCESSING', claimed_at = CURRENT_TIMESTAMP, claim_token = #{token,jdbcType=VARCHAR}
FROM cand t
WHERE o.id = t.id
  AND o.status = 'PENDING'
